import 'dart:io';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter_test/flutter_test.dart';

/// Contract tests for the launcher icon source asset (TOOL-06, U-20).
///
/// `assets/icons/app_icon.png` is the single regenerable source for every
/// platform launcher icon (generated by `tool/icon_gen.dart`, wired via
/// flutter_launcher_icons). It must decode to exactly 1024x1024 and carry
/// the disco identity — black background with a glowing pink/white shard —
/// i.e. it can never be a flat color.
void main() {
  const sourcePath = 'assets/icons/app_icon.png';
  const size = 1024;

  Future<ui.Image> decodeSource() async {
    final bytes = File(sourcePath).readAsBytesSync();
    final codec = await ui.instantiateImageCodec(bytes);
    final frame = await codec.getNextFrame();
    return frame.image;
  }

  int samplePixel(
    ByteData data,
    int width,
    int x,
    int y,
    int channel,
  ) {
    return data.getUint8((y * width + x) * 4 + channel);
  }

  double luminanceAt(ByteData data, int width, int x, int y) {
    final r = samplePixel(data, width, x, y, 0) / 255.0;
    final g = samplePixel(data, width, x, y, 1) / 255.0;
    final b = samplePixel(data, width, x, y, 2) / 255.0;
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  }

  group('launcher icon source asset (TOOL-06/U-20)', () {
    test('decodes as a 1024x1024 PNG', () async {
      final image = await decodeSource();
      expect(image.width, size, reason: 'launcher source must be 1024 wide');
      expect(image.height, size, reason: 'launcher source must be 1024 tall');
      image.dispose();
    });

    test('pixels are non-uniform: black background with a glowing shard '
        'center', () async {
      final image = await decodeSource();
      final data =
          (await image.toByteData(format: ui.ImageByteFormat.rawRgba))!;

      // Corners are the P1 black background (grain keeps them non-flat but
      // they must stay essentially black — luminance < 0.1).
      const corners = <(int, int)>[
        (0, 0),
        (size - 1, 0),
        (0, size - 1),
        (size - 1, size - 1),
        (size ~/ 2, 1),
        (1, size ~/ 2),
      ];
      for (final (x, y) in corners) {
        expect(
          luminanceAt(data, image.width, x, y),
          lessThan(0.1),
          reason: 'corner ($x,$y) must be black (P1: black always)',
        );
      }

      // The center is the glow-pink shard — well above black.
      final centerLuma = luminanceAt(data, image.width, size ~/ 2, size ~/ 2);
      expect(
        centerLuma,
        greaterThan(0.25),
        reason: 'the icon center must carry the brand shard, got '
            'luminance $centerLuma',
      );

      // Non-uniform proof: the sampled set holds at least two distinct
      // colors (black background vs pink/white shard).
      final distinct = <String>{
        for (var y = 0; y < size; y += size ~/ 8)
          for (var x = 0; x < size; x += size ~/ 8)
            '${samplePixel(data, image.width, x, y, 0)},'
                '${samplePixel(data, image.width, x, y, 1)},'
                '${samplePixel(data, image.width, x, y, 2)}',
      };
      expect(
        distinct.length,
        greaterThanOrEqualTo(2),
        reason: 'the icon must not be a flat color — got $distinct',
      );

      image.dispose();
    });
  });
}
